#include <iostream>
#include <vector>
#include <memory>
#include <algorithm>
using namespace std;

class SortingStrategy {
public:
    virtual void sort(vector<int>& v) = 0;
    virtual ~SortingStrategy() {}
};

class BubbleSort : public SortingStrategy {
public:
    void sort(vector<int>& v) override {
        for (size_t i = 0; i < v.size()-1; i++)
            for (size_t j = 0; j < v.size()-i-1; j++)
                if (v[j] > v[j+1]) swap(v[j], v[j+1]);
    }
};

class Sorter {
    unique_ptr<SortingStrategy> strategy;
public:
    void setStrategy(unique_ptr<SortingStrategy> s) { strategy = move(s); }
    void execute(vector<int>& v) { strategy->sort(v); }
};

int main() {
    vector<int> v1 = {5,2,9,1,5};
    Sorter s;
    s.setStrategy(make_unique<BubbleSort>());
    s.execute(v1);
    for (int x : v1) cout << x << " ";
    cout << endl;
    return 0;
}
